  1014→function normalizeSheetName(name) {
  1015→  let result = '';
  1016→  for (let i = 0; i < name.length; i++) {
  1017→    const ch = name[i];
  1018→    result += KANGXI_MAP[ch] || ch;
  1019→  }
  1020→  return result;
  1021→}
  1022→// Build a lookup: given a sheets object, find sheet by normalized name
  1023→function findSheet(sheets, name) {
  1024→  if (sheets[name]) return sheets[name];
  1025→  const norm = normalizeSheetName(name);
  1026→  for (const key of Object.keys(sheets)) {
  1027→    if (normalizeSheetName(key) === norm) return sheets[key];
  1028→  }
  1029→  return null;
  1030→}
  1031→// Get the actual key name in sheets object
  1032→function findSheetKey(sheets, name) {
  1033→  if (sheets[name] !== undefined) return name;
  1034→  const norm = normalizeSheetName(name);
  1035→  for (const key of Object.keys(sheets)) {
  1036→    if (normalizeSheetName(key) === norm) return key;
  1037→  }
  1038→  return null;
  1039→}
  1040→
  1041→/* ====== Utility Functions ====== */
  1042→function isNumeric(v) {
  1043→  if (v == null) return false;
  1044→  if (typeof v === 'number') return isFinite(v);
  1045→  if (typeof v === 'string') { const n = parseFloat(v); return !isNaN(n) && isFinite(n); }
  1046→  return false;
  1047→}
  1048→function toFloat(v) {
  1049→  if (v == null) return null;
  1050→  if (typeof v === 'number') return isFinite(v) ? v : null;
  1051→  if (typeof v === 'string') {
  1052→    if (v === '' || v === 'nan' || v === 'inf' || v === '-inf') return null;
  1053→    const n = parseFloat(v);
  1054→    return isFinite(n) ? n : null;
  1055→  }
  1056→  return null;
  1057→}
  1058→function escHtml(s) {
  1059→  if (s == null) return '';
  1060→  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  1061→}
  1062→
  1063→/* ====== Normalized Set Matching ====== */
  1064→function setHasNorm(theSet, name) {
  1065→  if (theSet.has(name)) return true;
  1066→  const norm = normalizeSheetName(name);
  1067→  for (const item of theSet) {
  1068→    if (normalizeSheetName(item) === norm) return true;
  1069→  }
  1070→  return false;
  1071→}
  1072→
  1073→/* ====== Column Type Detection ====== */
  1074→function detectColumnTypes(data, sheetName) {
  1075→  if (!data || !data[0]) return {};
  1076→  const headers = data[0];
  1077→  const colTypes = {};
  1078→  for (let ci = 0; ci < headers.length; ci++) {
  1079→    const h = String(headers[ci] || '');
  1080→    if (setHasNorm(PCT_RAW_SHEETS, sheetName)) {
  1081→      if (/年化|收益率|波动率|占比/.test(h)) { colTypes[ci] = 'percent_raw'; continue; }
  1082→    }
  1083→    if (setHasNorm(PCT_DECIMAL_SHEETS, sheetName)) {
  1084→      if (/年化|收益率|波动率|占比/.test(h)) { colTypes[ci] = 'percent'; continue; }
  1085→    }
  1086→    if (/bp/i.test(h)) { colTypes[ci] = 'bps'; continue; }
  1087→    const isPctHeader = /年化|收益率|波动率|占比|比例/.test(h);
  1088→    const numVals = [];
  1089→    for (let ri = 1; ri < Math.min(data.length, 20); ri++) {
  1090→      if (ci < data[ri].length) {
  1091→        const v = toFloat(data[ri][ci]);
  1092→        if (v != null && v !== 0) numVals.push(Math.abs(v));
  1093→      }
  1094→    }
  1095→    if (isPctHeader) {
  1096→      if (numVals.length > 0) {
  1097→        const avg = numVals.reduce((a,b) => a+b, 0) / numVals.length;
  1098→        colTypes[ci] = avg > 0.5 ? 'percent_raw' : 'percent';
  1099→      } else { colTypes[ci] = 'percent'; }
  1100→    } else if (numVals.length >= 2) {
  1101→      const avg = numVals.reduce((a,b) => a+b, 0) / numVals.length;
  1102→      const mx = Math.max(...numVals);
  1103→      if (avg > 0 && avg < 0.5 && mx < 1.5) colTypes[ci] = 'percent';
  1104→    }
  1105→  }
  1106→  return colTypes;
  1107→}
  1108→
  1109→/* ====== Cell Value Formatting ====== */
  1110→function formatCellValue(val, colType, useParens) {
  1111→  if (val == null) return '';
  1112→  if (typeof val === 'string') {
  1113→    if (val === 'nan' || val === 'inf' || val === '-inf') return '';
  1114→    const n = parseFloat(val);
  1115→    if (isFinite(n)) val = n; else return escHtml(val);
  1116→  }
  1117→  if (typeof val !== 'number' || !isFinite(val)) return '';
  1118→  if (colType === 'percent') return (val * 100).toFixed(2) + '%';
  1119→  if (colType === 'percent_raw') return val.toFixed(2) + '%';
  1120→  if (colType === 'bps') return val.toFixed(2);
  1121→  if (useParens) {
  1122→    if (Math.abs(val) < 0.05) return '-';
  1123→    if (Math.abs(val) < 1 && Math.abs(val) >= 0.05)
  1124→      return val < 0 ? '(' + Math.abs(val).toFixed(1) + ')' : val.toFixed(1);
  1125→    const r = Math.round(val);
  1126→    if (r === 0) return '-';
  1127→    if (r < 0) return '(' + Math.abs(r).toLocaleString() + ')';
  1128→    return r.toLocaleString();
  1129→  }
  1130→  if (Number.isInteger(val) || (val === Math.floor(val) && Math.abs(val) < 10000)) return String(Math.floor(val));
  1131→  if (Math.abs(val) < 0.0001 && val !== 0) return val.toFixed(6);
  1132→  if (Math.abs(val) < 0.01 && val !== 0) return val.toFixed(4);
  1133→  if (Math.abs(val) < 100) return val.toFixed(2);
  1134→  if (Math.abs(val) < 100000) return val.toLocaleString(undefined, {minimumFractionDigits:2, maximumFractionDigits:2});
  1135→  return Math.round(val).toLocaleString();
  1136→}
  1137→
  1138→/* ====== Cell CSS Classes ====== */
  1139→function getCellClass(val, colType, header) {
  1140→  const fval = toFloat(val);
  1141→  if (fval == null) return '';
  1142→  const h = String(header).toLowerCase();
  1143→  const classes = [];
  1144→  const isChange = /变化|较上周|较上月|较上年|bp/.test(h);
  1145→  const isReturn = /年化|收益率/.test(h);
  1146→  if (isChange) { if (fval > 0) classes.push('val-positive'); else if (fval < 0) classes.push('val-negative'); }
  1147→  if (isReturn && colType === 'percent' && fval < 0) classes.push('val-negative');
  1148→  if (isChange && fval !== 0) {
  1149→    let intensity;
  1150→    if (colType === 'percent') intensity = Math.min(Math.abs(fval) * 20, 1);
  1151→    else if (colType === 'percent_raw') intensity = Math.min(Math.abs(fval) / 5, 1);
  1152→    else if (/bp/.test(h)) intensity = Math.min(Math.abs(fval) / 50, 1);
  1153→    else intensity = Math.min(Math.abs(fval) / 20, 1);
  1154→    const level = Math.min(Math.floor(intensity * 5) + 1, 5);
  1155→    classes.push(fval > 0 ? 'heat-pos-' + level : 'heat-neg-' + level);
  1156→  }
  1157→  return classes.join(' ');
  1158→}
  1159→
  1160→/* ====== Preprocessing ====== */
  1161→function preprocessSheets(sheets) {
  1162→  // 1. 分渠道余额 subtotals
  1163→  const ch = findSheet(sheets, '1、分渠道余额');
  1164→  if (ch && ch.data && ch.data.length > 3) {
  1165→    const d = ch.data;
  1166→    const newData = d.slice(0, 3);
  1167→    const groups = {};
  1168→    let curGroup = null;
  1169→    for (let ri = 3; ri < d.length; ri++) {
  1170→      const row = d[ri];
  1171→      if (row[0] != null) curGroup = String(row[0]);
  1172→      if (curGroup) { if (!groups[curGroup]) groups[curGroup] = []; groups[curGroup].push(row); }
  1173→    }
  1174→    const grandTotal = [0, 0];
  1175→    for (const gn of ['中低波稳健产品', '中高波市值产品', '外币产品']) {
  1176→      const rows = groups[gn] || [];
  1177→      const sub = [0, 0];
  1178→      for (const row of rows) {
  1179→        const v1 = toFloat(row[2]); const v2 = toFloat(row[3]);
  1180→        if (v1) sub[0] += v1; if (v2) sub[1] += v2;
  1181→        newData.push(row);
  1182→      }
  1183→      newData.push([null, gn + '合计', Math.round(sub[0]), Math.round(sub[1])]);
  1184→      grandTotal[0] += sub[0]; grandTotal[1] += sub[1];
  1185→    }
  1186→    if (newData[0].length === 4) {
  1187→      newData[0] = [null, null, '保有规模', null, null];
  1188→      newData[1] = [null, '渠道-行内外', '行内', '行外', '合计'];
  1189→      newData[2] = ['总分类', '母分类', null, null, null];
  1190→    }
  1191→    for (let ri = 3; ri < newData.length; ri++) {
  1192→      const row = newData[ri];
  1193→      if (row.length === 4) { row.push(Math.round((toFloat(row[2])||0) + (toFloat(row[3])||0))); }
  1194→    }
  1195→    newData.push([null, '总计', Math.round(grandTotal[0]), Math.round(grandTotal[1]),
  1196→                  Math.round(grandTotal[0] + grandTotal[1])]);
  1197→    ch.data = newData; ch.col_count = 5;
  1198→  }
  1199→
  1200→  // 2. 产品规模 合计
  1201→  const ps = findSheet(sheets, '2、产品规模');
  1202→  if (ps && ps.data && ps.data.length > 1) {
  1203→    const d = ps.data;
  1204→    const hasTotal = d.slice(1).some(r => {
  1205→      const a = String(r[0]||'').trim(); const b = String(r[1]||'').trim();
  1206→      return a === '合计' || a === '总计' || b === '合计' || b === '总计';
  1207→    });
  1208→    if (!hasTotal) {
  1209→      const totals = new Array(d[0].length).fill(0);
  1210→      for (const row of d.slice(1)) {
  1211→        for (let ci = 2; ci < row.length; ci++) { const v = toFloat(row[ci]); if (v) totals[ci] += v; }
  1212→      }
  1213→      const totalRow = ['', '合计'];
  1214→      for (let ci = 2; ci < d[0].length; ci++) totalRow.push(Math.round(totals[ci]));
  1215→      while (totalRow.length < d[0].length) totalRow.push(null);
  1216→      d.push(totalRow);
  1217→    }
  1218→  }
  1219→
  1220→  // 3. 投资经理维度 合计
  1221→  const pm = findSheet(sheets, '投资经理维度产品规模和数量');
  1222→  if (pm && pm.data && pm.data.length > 1) {
  1223→    const d = pm.data;
  1224→    const hasTotal = d.slice(1).some(r => String(r[0]||'').trim() === '合计');
  1225→    if (!hasTotal) {
  1226→      const totals = new Array(d[0].length).fill(0);
  1227→      for (const row of d.slice(1)) {
  1228→        for (let ci = 1; ci < row.length; ci++) { const v = toFloat(row[ci]); if (v) totals[ci] += v; }
  1229→      }
  1230→      const totalRow = ['合计'];
  1231→      for (let ci = 1; ci < d[0].length; ci++) totalRow.push(Math.round(totals[ci] * 10) / 10);
  1232→      while (totalRow.length < d[0].length) totalRow.push(null);
  1233→      d.push(totalRow);
  1234→    }
  1235→  }
  1236→}
