  1238→/* ====== Table HTML Generation ====== */
  1239→function generateTableHTML(sheetName, sheetData) {
  1240→  if (!sheetData || !sheetData.data || sheetData.data.length === 0) return '<div class="empty-state">暂无数据</div>';
  1241→  const data = sheetData.data;
  1242→  const colTypes = detectColumnTypes(data, sheetName);
  1243→  const useParens = setHasNorm(SCALE_INT_SHEETS, sheetName);
  1244→  const numCols = sheetData.col_count || (data[0] ? data[0].length : 0);
  1245→  let html = '';
  1246→  for (let ri = 0; ri < data.length; ri++) {
  1247→    const row = data[ri];
  1248→    const isHeader = ri === 0;
  1249→    let isSubheader = false;
  1250→    if (ri === 1 || ri === 2) {
  1251→      const vals = row.filter(v => v != null);
  1252→      const numC = vals.filter(v => isNumeric(v)).length;
  1253→      if (vals.length > 0 && (vals.length - numC) > numC && (vals.length - numC) >= 2) isSubheader = true;
  1254→    }
  1255→    let cells = '';
  1256→    for (let ci = 0; ci < Math.min(row.length, numCols); ci++) {
  1257→      const val = row[ci];
  1258→      const tag = (isHeader || (isSubheader && ri < 3)) ? 'th' : 'td';
  1259→      const colH = data[0][ci] != null ? String(data[0][ci]) : '';
  1260→      const colType = colTypes[ci] || null;
  1261→      let display;
  1262→      if (isHeader || (isSubheader && ri < 3)) { display = val != null ? escHtml(String(val)) : ''; }
  1263→      else { display = formatCellValue(val, colType, useParens); }
  1264→      let cls = [];
  1265→      if (!isHeader && !isSubheader) {
  1266→        const cc = getCellClass(val, colType, colH); if (cc) cls.push(cc);
  1267→        if (toFloat(val) != null) cls.push('num-cell');
  1268→      }
  1269→      const clsStr = cls.length ? ' class="' + cls.join(' ') + '"' : '';
  1270→      cells += '<' + tag + clsStr + '>' + display + '</' + tag + '>';
  1271→    }
  1272→    let rowCls = '';
  1273→    if (isHeader) rowCls = 'header-row';
  1274→    else if (isSubheader && ri < 3) rowCls = 'subheader-row';
  1275→    else if (row.length > 0) {
  1276→      const f = String(row[0]||'').trim();
  1277→      const s = row.length > 1 ? String(row[1]||'').trim() : '';
  1278→      if (['合计','总计','总合计','汇总','总规模'].includes(f) || ['合计','总计','汇总'].includes(s))
  1279→        rowCls = 'total-row';
  1280→      else if (s.includes('合计')) rowCls = 'subtotal-row';
  1281→      else if (row.slice(0,3).some(v => String(v||'').includes('合计'))) rowCls = 'total-row';
  1282→    }
  1283→    const rcAttr = rowCls ? ' class="' + rowCls + '"' : '';
  1284→    html += '<tr' + rcAttr + '>' + cells + '</tr>';
  1285→  }
  1286→  return '<div class="table-wrapper"><table>' + html + '</table></div>';
  1287→}
