  1289→/* ====== Overview Stats ====== */
  1290→function computeOverviewStats(sheets) {
  1291→  const stats = {};
  1292→  const ps = findSheet(sheets, '2、产品规模');
  1293→  if (ps && ps.data) {
  1294→    let totalAum = 0, totalCount = 0, aumM = 0, aumY = 0;
  1295→    for (const row of ps.data.slice(1)) {
  1296→      const f = String(row[0]||'').trim(); const s = String(row[1]||'').trim();
  1297→      if (['合计','总计'].includes(f) || ['合计','总计'].includes(s)) continue;
  1298→      let v = toFloat(row[2]); if (v) totalAum += v;
  1299→      v = toFloat(row[5]); if (v) totalCount += v;
  1300→      v = toFloat(row[3]); if (v) aumM += v;
  1301→      v = toFloat(row[4]); if (v) aumY += v;
  1302→    }
  1303→    stats.totalAum = totalAum; stats.totalCount = totalCount;
  1304→    stats.aumM = aumM; stats.aumY = aumY;
  1305→  }
  1306→  const ts = findSheet(sheets, '总结文字');
  1307→  if (ts && ts.data) {
  1308→    for (const row of ts.data.slice(1)) {
  1309→      if (row.length >= 2 && row[0] && row[1]) {
  1310→        const k = String(row[0]); const v = String(row[1]);
  1311→        if (k.includes('规模')) stats.guimoText = v;
  1312→        else if (k.includes('中收')) stats.zhongshouText = v;
  1313→        else if (k.includes('到期')) stats.daoqiText = v;
  1314→      }
  1315→    }
  1316→  }
  1317→  const bp = findSheet(sheets, '破净结果');
  1318→  if (bp && bp.data) stats.brokenCount = bp.data.slice(1).filter(r => r.some(v => v != null)).length;
  1319→  const up = findSheet(sheets, '招商在售产品不达基准');
  1320→  if (up && up.data) stats.underperformCount = up.data.length - 1;
  1321→  const hv = findSheet(sheets, '12.周净值高波动产品清单');
  1322→  if (hv && hv.data) stats.highVolCount = hv.data.length - 1;
  1323→  return stats;
  1324→}
