  1326→function generateOverviewHTML(stats, sheets) {
  1327→  const aum = stats.totalAum;
  1328→  const aumStr = aum > 100 ? Math.round(aum).toLocaleString() + '亿' : (aum ? aum.toFixed(2) + '亿' : 'N/A');
  1329→  const countStr = stats.totalCount ? Math.round(stats.totalCount) + '只' : 'N/A';
  1330→  const aumMStr = stats.aumM != null ? (stats.aumM >= 0 ? '+' : '') + Math.round(stats.aumM) + '亿' : 'N/A';
  1331→  const aumMCls = stats.aumM > 0 ? 'stat-positive' : (stats.aumM < 0 ? 'stat-negative' : '');
  1332→  const aumYStr = stats.aumY != null ? (stats.aumY >= 0 ? '+' : '') + Math.round(stats.aumY) + '亿' : 'N/A';
  1333→  const aumYCls = stats.aumY > 0 ? 'stat-positive' : (stats.aumY < 0 ? 'stat-negative' : '');
  1334→  const broken = stats.brokenCount || 0;
  1335→  const brokenCls = broken > 0 ? 'stat-alert' : 'stat-ok';
  1336→  const brokenStr = broken > 0 ? broken + '只' : '无';
  1337→  const underperf = stats.underperformCount || 0;
  1338→  const highVol = stats.highVolCount || 0;
  1339→  let textCards = '';
  1340→  for (const [key, label] of [['guimoText','规模概况'],['zhongshouText','中收概况'],['daoqiText','到期概况']]) {
  1341→    const text = stats[key] || '';
  1342→    if (text) textCards += '<div class="text-card"><div class="text-card-label">' + label +
  1343→      '</div><div class="text-card-content">' + escHtml(text).replace(/\n/g, '<br>') + '</div></div>';
  1344→  }
  1345→  // Bar chart
  1346→  let barItems = '';
  1347→  const ps = findSheet(sheets, '2、产品规模');
  1348→  if (ps && ps.data) {
  1349→    let maxAum = 0;
  1350→    for (const row of ps.data.slice(1)) {
  1351→      const s = String(row[1]||'').trim();
  1352→      if (['合计','总计'].includes(s)) continue;
  1353→      const v = toFloat(row[2]); if (v && v > maxAum) maxAum = v;
  1354→    }
  1355→    for (const row of ps.data.slice(1)) {
  1356→      const name = String(row[1] || '');
  1357→      if (['合计','总计'].includes(name.trim())) continue;
  1358→      const v = toFloat(row[2]) || 0;
  1359→      const chg = toFloat(row[3]) || 0;
  1360→      if (v && name) {
  1361→        const pct = maxAum > 0 ? (v / maxAum * 100) : 0;
  1362→        const color = chg > 0 ? 'var(--positive)' : (chg < 0 ? 'var(--negative)' : 'var(--accent-blue)');
  1363→        barItems += '<div class="bar-row"><div class="bar-label" title="'+escHtml(name)+'">'+escHtml(name.slice(0,8))+
  1364→          '</div><div class="bar-track"><div class="bar-fill" style="width:'+pct.toFixed(1)+'%;background:'+color+
  1365→          '"></div></div><div class="bar-value">'+Math.round(v)+'</div></div>';
  1366→      }
  1367→    }
  1368→  }
  1369→  return '<div class="overview-grid">'+
  1370→    '<div class="stat-card stat-primary"><div class="stat-label">管理规模</div><div class="stat-value">'+aumStr+'</div>'+
