  1372→    '<div class="stat-card"><div class="stat-label">产品数量</div><div class="stat-value">'+countStr+'</div></div>'+
  1373→    '<div class="stat-card '+brokenCls+'"><div class="stat-label">破净产品</div><div class="stat-value">'+brokenStr+'</div></div>'+
  1374→    '<div class="stat-card '+(underperf>3?'stat-alert':'')+'"><div class="stat-label">不达基准</div><div class="stat-value">'+underperf+'只</div></div>'+
  1375→    '<div class="stat-card '+(highVol>20?'stat-alert':'')+'"><div class="stat-label">高波动产品</div><div class="stat-value">'+highVol+'只</div></div>'+
  1376→    '</div>'+
  1377→    '<div class="overview-grid" style="grid-template-columns:1fr 1fr;">'+
  1378→    '<div class="stat-card" style="padding:14px 18px"><div class="stat-label" style="margin-bottom:10px">各系列规模分布 (亿)</div><div class="bar-chart">'+barItems+'</div></div>'+
  1379→    '<div class="stat-card" style="padding:14px 18px"><div class="stat-label" style="margin-bottom:6px">AI 摘要</div><div class="text-cards-inline">'+textCards+'</div></div>'+
  1380→    '</div>';
  1381→}
