  1383→/* ====== Rebuild Dashboard ====== */
  1384→function rebuildDashboard(sheets) {
  1385→  for (const section of SECTION_CONFIG) {
  1386→    const el = document.getElementById(section.id);
  1387→    if (!el) continue;
  1388→    // Keep the section header
  1389→    const header = el.querySelector('.section-header');
