  1393→    if (section.type === 'overview') {
  1394→      const stats = computeOverviewStats(sheets);
  1395→      contentHTML = generateOverviewHTML(stats, sheets);
  1396→    } else if (section.type === 'tabs') {
  1397→      let tabBtns = '', tabContents = '';
