  1405→        tabBtns += '<button class="tab-btn'+active+'" onclick="switchTab(\''+section.id+'\','+tabIdx+')" '+
  1406→          'data-tabgroup="'+section.id+'" data-tabidx="'+tabIdx+'">'+escHtml(short)+'</button>';
  1407→        tabContents += '<div class="tab-content'+active+'" data-tab="'+section.id+'-tab-'+tabIdx+'" data-tab-label="'+escHtml(short)+'">'+
  1408→          generateTableHTML(actualKey, sd)+'</div>';
