  1437→async function handleFileUpload(e) {
  1438→  const file = e.target.files[0];
  1439→  if (!file) return;
  1440→  if (!file.name.endsWith('.xlsx') && !file.name.endsWith('.xls')) {
  1441→    showToast('请上传 .xlsx 格式的Excel文件', 'error');
  1442→    return;
  1443→  }
  1444→  showToast('正在解析 ' + escHtml(file.name) + ' ...', '');
  1445→  try {
  1446→    const arrayBuf = await file.arrayBuffer();
  1447→    const wb = XLSX.read(arrayBuf, { type: 'array' });
  1448→    const sheets = {};
  1449→    for (const name of wb.SheetNames) {
  1450→      const ws = wb.Sheets[name];
  1451→      const jsonData = XLSX.utils.sheet_to_json(ws, { header: 1, defval: null, raw: true });
  1452→      // Get merged cells
  1453→      const mergedCells = (ws['!merges'] || []).map(m => XLSX.utils.encode_range(m));
  1454→      sheets[name] = {
  1455→        data: jsonData,
  1456→        col_count: jsonData[0] ? jsonData[0].length : 0,
  1457→        merged_cells: mergedCells
  1458→      };
  1459→    }
  1460→    // Preprocess
  1461→    preprocessSheets(sheets);
  1462→    // Rebuild
  1463→    rebuildDashboard(sheets);
  1464→    // Update date from filename
  1465→    const dateMatch = file.name.match(/(\d{8})/);
  1466→    if (dateMatch) {
  1467→      const d = dateMatch[1];
  1468→      const dateStr = d.slice(0,4) + '-' + d.slice(4,6) + '-' + d.slice(6,8);
  1469→      document.querySelectorAll('.header-date').forEach(el => el.textContent = '数据截止 ' + dateStr);
  1470→      document.querySelectorAll('footer').forEach(el => {
  1471→        el.innerHTML = '兴银理财多资产投资部 | 数据截止 ' + dateStr + ' | 仪表板更新于 ' + new Date().toLocaleString('zh-CN');
  1472→      });
  1473→    }
  1474→    showToast('数据导入成功！已加载 ' + wb.SheetNames.length + ' 张工作表', 'success');
  1475→  } catch (err) {
  1476→    console.error(err);
  1477→    showToast('解析失败: ' + escHtml(err.message), 'error');
  1478→  }
  1479→  e.target.value = '';
  1480→}
