  1506→function initNavHighlight() {
  1507→  const sections = document.querySelectorAll('.section');
  1508→  const navItems = document.querySelectorAll('.nav-item');
  1509→  const observer = new IntersectionObserver((entries) => {
  1510→    entries.forEach(entry => {
