  1539→    const query = e.target.value.toLowerCase().trim();
  1540→    document.querySelectorAll('table').forEach(table => {
  1541→      table.querySelectorAll('tr:not(.header-row):not(.subheader-row)').forEach(row => {
  1542→        if (!query) { row.style.display = ''; return; }
  1543→        row.style.display = row.textContent.toLowerCase().includes(query) ? '' : 'none';
