  1549→function initTableSort() {
  1550→  document.querySelectorAll('th').forEach(th => {
  1551→    th.style.cursor = 'pointer';
  1552→    th.addEventListener('click', () => {
  1553→      const table = th.closest('table');
  1554→      const idx = Array.from(th.parentNode.children).indexOf(th);
  1555→      const tbody = table.querySelector('tbody') || table;
  1556→      const rows = Array.from(tbody.querySelectorAll('tr')).filter(r =>
  1557→        !r.classList.contains('header-row') && !r.classList.contains('subheader-row') &&
  1558→        !r.classList.contains('total-row') && !r.classList.contains('subtotal-row'));
  1559→      const isAsc = th.getAttribute('data-sort') !== 'asc';
  1560→      th.setAttribute('data-sort', isAsc ? 'asc' : 'desc');
  1561→      rows.sort((a, b) => {
  1562→        const aVal = a.children[idx]?.textContent?.trim()?.replace(/[()]/g, '') || '';
  1563→        const bVal = b.children[idx]?.textContent?.trim()?.replace(/[()]/g, '') || '';
  1564→        const aNum = parseFloat(aVal.replace(/[,%亿万只]/g, ''));
  1565→        const bNum = parseFloat(bVal.replace(/[,%亿万只]/g, ''));
  1566→        if (!isNaN(aNum) && !isNaN(bNum)) return isAsc ? aNum - bNum : bNum - aNum;
  1567→        return isAsc ? aVal.localeCompare(bVal, 'zh') : bVal.localeCompare(aVal, 'zh');
  1568→      });
  1569→      rows.forEach(r => tbody.appendChild(r));
  1570→    });
  1571→  });
  1572→}
  1573→
  1574→document.addEventListener('DOMContentLoaded', () => {
  1575→  initNavHighlight();
  1576→  initSearch();
  1577→  initTableSort();
  1578→  // Bind upload
  1579→  const uploadInput = document.getElementById('file-upload');
  1580→  if (uploadInput) uploadInput.addEventListener('change', handleFileUpload);
  1581→});
  1582→
